function.arguments:
{"script":"while read -r p; do
  if [ -L "$p" ]; then
    target=$(readlink -f "$p")
    if [ ! -e "$p" ]; then status="broken";
    elif [[ "$target" == /var/* ]]; then status="inside /var";
    else status="outside /var"; fi
    echo "$p -> $target ($status)"
  fi
done < temp_var_count/all_paths.txt > temp_var_count/symlink_resolution.txt"}
